package pe.vichaval.gestionriego.notificacion;
import static org.junit.jupiter.api.Assertions.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.transaction.annotation.Transactional;
import pe.vichaval.gestionriego.agricultor.dto.AgricultorForm; import pe.vichaval.gestionriego.agricultor.service.AgricultorService; import pe.vichaval.gestionriego.integration.PostgreSqlIntegrationBase; import pe.vichaval.gestionriego.notificacion.service.NotificacionService;
@SpringBootTest @ActiveProfiles("test") @Transactional class NotificacionIT extends PostgreSqlIntegrationBase {
 @Autowired AgricultorService agricultores; @Autowired NotificacionService notificaciones;
 @Test void creaUnaSolaNotificacionPorClaveYPermiteLeerArchivar(){var a=agricultores.save(form(),null);var n=notificaciones.crearAgricultor(a.getId(),"AVISO_ADMINISTRATIVO","Aviso","Mensaje","MEDIA","PRUEBA",1L,"/dashboard","PRUEBA:1",null);assertNotNull(n);assertNull(notificaciones.crearAgricultor(a.getId(),"AVISO_ADMINISTRATIVO","Aviso","Mensaje","MEDIA","PRUEBA",1L,"/dashboard","PRUEBA:1",null));assertEquals(1,notificaciones.noLeidasAgricultor(a.getId()));notificaciones.leerAgricultor(n.getId(),a.getId());assertEquals(0,notificaciones.noLeidasAgricultor(a.getId()));notificaciones.archivarAgricultor(n.getId(),a.getId());assertTrue(notificaciones.agricultor(a.getId(),0).isEmpty());}
 @Test void impideAccesoCruzado(){var a=agricultores.save(form("73737373"),null);var b=agricultores.save(form("74747474"),null);var n=notificaciones.crearAgricultor(a.getId(),"AVISO_ADMINISTRATIVO","A","B","BAJA","P",2L,null,"P:2",null);assertThrows(IllegalArgumentException.class,()->notificaciones.leerAgricultor(n.getId(),b.getId()));}
 private AgricultorForm form(){return form("72727272");} private AgricultorForm form(String d){var f=new AgricultorForm();f.setDni(d);f.setNombres("Notificacion");f.setApellidos("Prueba");f.setTelefono("999999999");f.setSector("Norte");f.setEstado("ACTIVO");return f;}
}
